$_ADMINLANG['marketConnect']['socialbee']['about']['author'] = "- Ovi Negrean，SocialBee 首席执行官";
$_ADMINLANG['marketConnect']['socialbee']['about']['p1'] = "SocialBee 是一款一体化社交媒体管理工具，让用户能够从一个地方跨多个社交媒体网络分享内容。您可以设置发布时间表、分享内容、分析表现并与关注者互动。";
$_ADMINLANG['marketConnect']['socialbee']['about']['p2'] = "SocialBee 成立于 2016 年，旨在简化各种规模企业的社交媒体管理。自推出以来，该平台已发展成为一个强大的工具，使用户能够从一个地方创建、安排、分析和参与跨各种平台的内容。凭借对用户友好设计的强调和强大的功能（如基于类别的调度和分析），SocialBee 被企业家、营销人员和机构所信赖，以优化其社交媒体形象并与受众建立有意义的联系。";
$_ADMINLANG['marketConnect']['socialbee']['about']['quote'] = "“在 SocialBee，我们的使命是赋能企业成功运营社交媒体，而无需应对使用多种工具的压力。SocialBee 被全球数千名用户所信赖，我们将强大的功能与以客户为中心的方法相结合，以确保您的成功。无论您是刚刚起步还是管理大量社交媒体账户，SocialBee 都将一路为您提供帮助。”";
$_ADMINLANG['marketConnect']['socialbee']['about']['title'] = "关于我们";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h1'] = "您可以使用 SocialBee 管理哪些社交媒体平台？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h2'] = "SocialBee 用户有哪些支持选项？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h3'] = "SocialBee 的代理计划与常规 Pro 计划有何不同？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h4'] = "SocialBee 的服务器位于哪里？SocialBee 的数据存储在哪里？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h5'] = "为什么我应该销售社交媒体管理工具？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h6'] = "企业会为社交媒体工具付费吗？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q1'] = "您可以管理和安排 Facebook、Instagram、Threads、X™（前 Twitter™）、LinkedIn、Pinterest、Google Business Profile™、TikTok、YouTube™ 和 Bluesky 等热门平台的内容。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q2'] = "用户可以通过聊天、<a href=\"mailto:hello@socialbee.com\">电子邮件</a>、<a href=\"https://socialbee.com/calendar\">电话</a>和<a href=\"https://help.socialbee.com\">丰富的知识库</a>（包含大量有用资源）获得 SocialBee 的帮助。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q3'] = "代理计划（Pro50、Pro100 和 Pro150）具有与 Pro 计划相同的功能。主要区别在于您可以连接的社交媒体资料数量、工作区数量以及可以添加到工作区的用户数量：";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q4'] = "SocialBee 的服务器位于欧洲爱尔兰。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q5'] = "销售像 SocialBee 这样的社交媒体管理工具可以让您利用对社交媒体营销解决方案日益增长的需求。中小型企业需要工具来管理其社交媒体资料、节省时间并提高参与度——这为您这样的经销商创造了强大的市场。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q6'] = "是的，中小型企业正在迅速投资社交媒体工具来管理其社交媒体形象。作为最常用的营销渠道之一，社交媒体有助于业务增长，企业渴望投资可靠的工具来帮助他们实现目标。";
$_ADMINLANG['marketConnect']['socialbee']['features']['f1']['p1'] = "SocialBee 与 Canva、Unsplash 和 GIPHY 集成，因此您可以轻松创建和策划帖子的视觉效果。";
