$_ADMINLANG['marketConnect']['xoviNow']['about']['h1'] = "XOVI NOW";
$_ADMINLANG['marketConnect']['xoviNow']['about']['h2'] = "关于 XOVI NOW（产品历史）";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p1'] = "企业需要特定的专业知识和合适的 SEO 工具，才能让他们的网站在 Google® 搜索结果中名列前茅。没有关键词研究、网站分析和竞争对手分析，就无法想象如何为产品和服务创造可见性。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p2'] = "借助合适的 SEO 工具，中小企业可以轻松完成这些任务，从而创建高质量的内容，推动和支持其企业网站的搜索引擎优化。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p3'] = "XOVI NOW 专为中小企业而设计。作为 SEO 专家，我们与众多企业主交谈过，评估了众多企业网站的优缺点，并利用我们自己的 SEO 专业知识设计了一款产品，让每个人都能轻松使用 SEO 的复杂功能。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p4'] = "XOVI NOW 使中小企业能够找到相关关键词，优化现有内容，并在不聘请 SEO 专家或超出预算的情况下撰写新的博客文章。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p5'] = "当您的客户选择 XOVI NOW 时，他们就选择了顺畅的入门体验和逐步指导，帮助他们随着时间的推移变得越来越显眼。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p6'] = "XOVI NOW 是 WebPros 扩展家族的最新成员。于 2022 年 2 月推出，它提供了超现代的关键词、排名跟踪和竞争对手分析工具。XOVI 是 WebPros 旗下的一家知名 SEO 行业品牌，拥有 13 年以上的经验，是领先的搜索引擎优化 SaaS 开发商。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p7'] = "WebPros 提供最具创新性的技术，赋能数字世界。我们汇集产品和解决方案，帮助企业构建、运营和在线增长。我们的产品帮助管理服务器、网站、计费和在线营销。WebPros 拥有一支专门的 SEO 专家团队，他们致力于实现 XOVI NOW，并投入数月的研究，以找到针对中小企业和 SEO 初学者的正确方法。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a1a'] = "由于成熟的 SEO 产品专注于 SEO 专家和技术娴熟的用户，提供令人眼花缭乱的功能集，XOVI NOW 的愿景是成为搜索引擎优化行业的网站建设器等效产品。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a1b'] = "XOVI NOW 易于使用和理解。它提供正确的功能集和指导，让客户随着时间的推移不断成长。由于中小企业对价格敏感，XOVI NOW 以极具竞争力的价格提供，既具有吸引力又不失产品质量。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a2a'] = "XOVI NOW 是一款 SaaS 解决方案。您不需要任何其他 WebPros 产品或扩展来使用 XOVI NOW，也不需要自己的服务器。XOVI NOW 完全独立运行，可用于世界上任何地方托管的任何网站。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a2b'] = "这也意味着您可以从任何计算机上的任何浏览器通过简单地登录您的账户来访问 XOVI NOW。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a3a'] = "每个网站所有者都知道在网上变得可见是多么困难。通过 XOVI NOW，我们提供了正确的功能来优化网站的可见性。通过爬取我们的数据库研究正确的关键词，每周或每天（取决于您的产品级别）跟踪您的排名，优化现有或新内容，并检查您的网站是否存在阻碍 Google® 排名的技术问题。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a4a'] = "我们全力支持经销商并提供协助。您的客户应该联系您，如果您无法给出满意的答案，我们会 100% 在那里为您提供尽可能快的帮助。只需通过<a href=\"https://support.xovinow.com/\" class=\"autoLinked\">XOVI NOW 工单系统</a>联系我们，我们的支持代理将很乐意提供帮助。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a5a'] = "项目基于特定的 URL（通常是您客户的网站），并自动创建站点审计（网站扫描以识别技术问题）。您的客户只需点击我们的入门向导即可设置项目。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a6a'] = "完全访问账户在 XOVI NOW 产品中拥有完全的管理权限。您可以更改、编辑和添加任何您想要的内容（例如，关键词、项目或任务）。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a6b'] = "只读账户可以访问 XOVI NOW 并查看产品提供的所有 SEO 见解，而无需编辑项目的任何方面。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a7a'] = "站点审计扫描您网站的技术实现，为 Google® 和其他搜索引擎提供更好的排名奠定基础。该工具允许您分析每个项目最多 10k 个页面/URL（XOVI NOW 入门级别为 500 个页面/项目）。扫描结果会自动添加到产品内的顾问工具中，并为每个问题创建精确的任务。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a7b'] = "扫描项目所需的时间很大程度上取决于页面/URL 的数量。较小的网站只需几分钟即可扫描完毕；较大的在线商店则需要几个小时才能彻底分析完毕。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8a'] = "该产品主要面向 SEO 初学者，他们对搜索引擎优化没有或只有很少的了解。如前所述，XOVI NOW 是专为中小企业设计的，并在该目标群体中进行了非常积极的测试。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8b'] = "通过 Pro 级别，我们提供了一个非常适合小型机构的选项。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8c'] = "由于功能集和超过 1 亿关键词的数据库，XOVI NOW 也非常适合高级 SEO 用户。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a9a'] = "将 XOVI NOW 与 SEMrush 进行比较就像是拿苹果和橙子比较，两者都不比对方更好。SEMrush 是一款针对专业 SEO 营销人员的产品，拥有 12 年以上的经验——它们提供针对不同需求的不同产品，不能被描述为全能工具。用户体验是为高级用户创建的，功能集对 SEO 初学者来说是压倒性的。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a9b'] = "SEMrush 是 SEO 专家和经验丰富的营销经理的正确选择，而 XOVI NOW 是初学者和需要更多成功道路上指导的用户的最佳选择。入门向导和 SEO 顾问等功能在已建立的产品中是找不到的。如果您的客户需要一个适合中小企业的完善产品，XOVI NOW 就是正确的选择。";
