$_ADMINLANG['supportticketdepts']['pop3oauthsetupinstructions']['Google'] = "<h1>Google OAuth 设置指南</h1><p>1. 登录 <a href=\"https://console.developers.google.com/\" target=\"_blank\">Google 开发者控制台</a>。</p><p>2. 选择现有项目或创建一个新项目。</p><p>3. 使用提供的<i>重定向 URI</i>创建 OAuth 凭据。</p><p>4. 将生成的<strong>客户端 ID/密钥</strong>填入下方字段中。</p><p>5. 点击<strong>“连接”</strong>以生成连接令牌。</p><p>6. 点击<strong>“测试配置”</strong>验证您的设置。</p>";
$_ADMINLANG['supportticketdepts']['pop3oauthsetupinstructions']['Microsoft'] = "<h1>Microsoft® OAuth 设置指南</h1><p>1. 登录 <a href=\"https://portal.azure.com/\" target=\"_blank\">Microsoft Azure® 控制台</a>。</p><p>2. 选择<strong>Azure Active Directory</strong>。</p><p>3. 使用显示的<strong>重定向 URI</strong>创建新的应用注册。</p><p>4. 输入生成的<strong>客户端 ID</strong>和<strong>客户端密钥</strong>。</p><p>5. 点击<strong>连接</strong>以生成连接令牌。</p><p>6. 点击<strong>“测试配置”</strong>验证您的设置。</p>";
